"""Read-only validation of M3.4 current preflight + explicitly synthetic rehearsal.

Raw BEA responses are local-only inputs, never generated by these tests. Outputs
are exclusive-write JSON; an interrupted output is preserved, not overwritten.
"""
from pathlib import Path
import argparse,copy,json
from research import m34_bea as b,m3_discovery as m,m31_access as a

def verify(study):
    root=m.safe_root(study);a.validate_root(root/'ACCESS',b.contract());plan=b.frozen(root)
    lists={};network=[]
    for p in (root/'ACCESS/HTTP').glob('*.reserve.json'):
        stem=p.with_name(p.name.replace('.reserve.json',''));ack,body,h=b.receipt(stem,b.contract())
        network.append({'request_id':stem.name,'url':ack['url'],'http':ack['http'],'request_started_at':ack['started_at'],'response_observed_at':ack['retrieved_at'],'retrieved_at':ack['retrieved_at'],'recorded_at':ack['durable_recorded_at'],'ack_prewrite_recorded_at':ack['recorded_at'],'receipt_sha256':h,'body_sha256':m.sha(body),'bytes':len(body),'duration_seconds':(b.utc(ack['retrieved_at'])-b.utc(ack['started_at'])).total_seconds()})
        if ack['endpoint_id'] in ('current','rss'):lists[stem.name]=b.release_list(ack['endpoint_id'],body)
    # The initial operator acquired original documents with the same unchanged
    # M3.1 transport under DOCUMENTS, before ITEM_* integration was implemented.
    binding=m.read(root/'DOCUMENT_BINDINGS.json');c=b.contract(binding['urls']);a.validate_root(root/'DOCUMENTS',c)
    docs={};origin=[]
    for ep,url in binding['urls'].items():
        stem=root/'DOCUMENTS/HTTP'/('preflight_'+ep);ack,body,h=b.receipt(stem,c)
        list_id=binding['source_list_receipts'][ep];rows=[r for r in lists[list_id] if r['source_url']==url]
        if len(rows)!=1:raise ValueError('LIVE_ORIGINAL_NOT_IN_REAL_LIST')
        doc=b.document(body,url)
        if doc['release_family']!=rows[0]['release_family']:raise ValueError('FAMILY_CONFLICT')
        d={**doc,**{k:v for k,v in rows[0].items() if k not in ('source_title_original',)},'receipt_sha256':h,'retrieved_at':ack['retrieved_at'],'recorded_at':ack['durable_recorded_at'],'evidence_layer':'ORIGINAL_DOCUMENT_NOT_AUTOMATIC_PROPOSITION_VERIFICATION'}
        docs[d['release_family']]=d
        item={'source_url':url,'release_family':d['release_family'],'receipt_sha256':h,'raw_sha256':m.sha(body),'content_sha256':d['content_sha256'],'real_request_started_at':ack['started_at'],'real_retrieved_at':ack['retrieved_at'],'real_recorded_at':ack['durable_recorded_at'],'source_list_receipt_id':list_id}
        origin.append(item)
        network.append({'request_id':stem.name,'url':url,'http':ack['http'],'request_started_at':ack['started_at'],'response_observed_at':ack['retrieved_at'],'retrieved_at':ack['retrieved_at'],'recorded_at':ack['durable_recorded_at'],'ack_prewrite_recorded_at':ack['recorded_at'],'receipt_sha256':h,'body_sha256':m.sha(body),'bytes':len(body),'duration_seconds':(b.utc(ack['retrieved_at'])-b.utc(ack['started_at'])).total_seconds()})
    current=lists['preflight_current'];rss=lists['preflight_rss']
    preflight={'status':'PASS','network_get':len(network),'network_bytes':sum(x['bytes'] for x in network),'responses':sorted(network,key=lambda x:x['request_started_at']),'schedule':plan['targets'],'schedule_plan_sha256':m.read(root/'M34_PLAN_SHA256.json')['sha256'],'upcoming_targets_observed':[],'current_release_families':[r['release_family'] for r in current],'rss_release_families':[r['release_family'] for r in rss],'rss_omits_current_pio_august':any(r['release_family']=='PIO_AUGUST_2026' for r in current) and not any(r['release_family']=='PIO_AUGUST_2026' for r in rss),'original_documents_verified':origin,'original_integration_scope':'LIVE_DOCUMENTS_RECEIPTS_VALIDATED_HERE; ITEM_PIPELINE_SEPARATELY_OFFLINE_TESTED','response_observed_semantics':'BODY_COMPLETION_NOT_HEADER_ARRIVAL','timestamp_scope':'REAL_CURRENT_PREFLIGHT_NOT_HISTORICAL_FIRST_SEEN','detection_latency':'UNKNOWN'}
    if preflight['network_get']!=b.budget(root)[0] or preflight['network_bytes']!=b.budget(root)[1] or len(network)>15 or preflight['network_bytes']>5_000_000:raise ValueError('ACCOUNTING_MISMATCH')
    if any(r['release_family'] in b.TARGETS for rows in lists.values() for r in rows):raise ValueError('FUTURE_TARGET_UNEXPECTED_REVIEW_REQUIRED')
    def simulated(family,clock,suffix=''):
        d=docs[family]
        return {k:v for k,v in {**d,'request_started_at':clock,'response_observed_at':clock,'retrieved_at':clock,'recorded_at':clock,'content_sha256':m.sha((d['content_sha256']+suffix).encode()) if suffix else d['content_sha256'],'fixture_origin_receipt_sha256':d['receipt_sha256'],'synthetic_change':suffix or None}.items() if k!='body_text'}
    jul=simulated('PIO_JULY_2026','2026-10-20T10:00:00Z')
    aug=simulated('PIO_AUGUST_2026','2026-10-20T10:31:00Z')
    gdp=simulated('GDP_Q2_2026_THIRD','2026-10-20T10:31:01Z')
    dup=simulated('PIO_AUGUST_2026','2026-10-20T11:02:00Z')
    updated=simulated('PIO_AUGUST_2026','2026-10-20T11:33:00Z','SYNTHETIC_BODY_REVISION_NOT_ACTUAL_BEA_CHANGE')
    repeat=simulated('PIO_AUGUST_2026','2026-10-20T12:04:00Z','SYNTHETIC_BODY_REVISION_NOT_ACTUAL_BEA_CHANGE')
    result=b.transitions([jul,aug,gdp,dup,updated,repeat],synthetic=True)
    actual=[r['observation_kind'] for r in result];expected=['NEW','NEW','NEW','DUPLICATE','UPDATED','DUPLICATE']
    unknown={**aug,'source_reported_published_at':None,'publication_precision':'UNKNOWN'}
    assert b.transitions([unknown],synthetic=True)[0]['source_reported_published_at'] is None
    invalid={**aug,'source_reported_published_at':'invalid'}
    try:b.transitions([invalid],synthetic=True);raise AssertionError('ACCEPTED_INVALID_CLOCK')
    except ValueError:pass
    assert len(b.transitions([jul],synthetic=True))==1 and b.transitions([],synthetic=True)==[]
    asof=b.transitions([jul,aug,gdp,dup,updated,repeat],as_of='2026-10-20T11:15:00Z',synthetic=True)
    assert all(x['observation_kind']!='UPDATED' for x in asof)
    assert actual==expected
    rehearsal={'status':'PASS','mode':'SYNTHETIC_HISTORICAL_TRANSITION_NOT_PROSPECTIVE','fixture_origin':origin,'actual_retrieval_clocks_unchanged':True,'controlled_clock_semantics':'ALL_10_TO_12_UTC_OBSERVATION_CLOCKS_ARE_SYNTHETIC_NOT_REAL_RECEIPTS','manually_checked_expected':expected,'actual':actual,'observations':result,'source_failure_emits_no_announcement':True,'one_family_without_other':True,'missing_time_remains_unknown':True,'invalid_clock_rejected':True,'future_update_excluded_asof':True,'upcoming_oct29_statistics_included':False,'synthetic_revision_not_real_source_revision':True}
    fact=b.income_fact(docs['PIO_AUGUST_2026'])
    handoff={'status':'PASS','mode':'REAL_HISTORICAL_DOCUMENT_STATEMENT_HANDOFF_REHEARSAL','discovery':'OFFICIAL_ORIGIN_NOT_INDEPENDENT_NEWS','official_fact':fact,'real_receipt_times':{k:docs['PIO_AUGUST_2026'][k] for k in ('retrieved_at','recorded_at')},'asof_scope':'DOCUMENT_AVAILABLE_TO_THIS_EXPERIMENT_ONLY_AFTER_REAL_ACK_RECORDING','future_oct29_gate':'NOT_TESTED','frozen_macroview':'UNAVAILABLE','production_integration':False}
    return {'M34_CURRENT_PREFLIGHT.json':preflight,'M34_OFFLINE_REHEARSAL_RESULTS.json':rehearsal,'M34_OFFICIAL_HANDOFF_REHEARSAL.json':handoff}

def main():
    p=argparse.ArgumentParser();p.add_argument('--study',required=True);p.add_argument('--output',required=True);v=p.parse_args()
    reports=verify(v.study);out=m.safe_root(v.output);m.assert_external_root(out)
    for name,obj in reports.items():m.save(out/name,obj)
    print(json.dumps({'status':'PASS','output_files':list(reports),'network_requests':0}))
if __name__=='__main__':main()
